using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S1.Dynamics.Symbolic.PermutativeLifts;

internal sealed class BalancedRegularRefutationDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S1/Dynamics/Symbolic/PermutativeLifts/BalancedRegularRefutation.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/Topology/kang2026lifts");
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The regular Toeplitz and strictly ergodic branch is refuted by one base.",
        H("The regular Toeplitz and strictly ergodic branch is refuted by one base"),
        Blocks(
            Describe.Lean(DescribeId.Create("construction"), DeclarationHandle.Create(Owner + "claim"),
                H("Literal regular and strictly ergodic hypothesis"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("The claim quantifies over all nonempty minimal binary subshifts having exactly one invariant probability measure and generated by an aperiodic Toeplitz point with a genuine essential period structure. The structure has positive nonempty essential periods, strict growth, divisibility and coverage of every signed coordinate. Its actual normalized periodic-skeleton densities converge to one. The conclusion asks for any allowed length and bipermutative local rule whose entire inverse image is minimal. This necessary condition also applies to a proposed strictly ergodic entire lift."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("main-result"), DeclarationHandle.Create(Owner + "result"),
                H("Literal negation using the same balanced base"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("One fixed balanced binary subshift discharges every hypothesis: its integer orbits are dense, its invariant probability is unique, and one actual regular aperiodic Toeplitz point generates exactly this subshift. For every length k+2 and every bipermutative rule, the full inverse image splits over this same base with actual prefix fibre Bool^(k+1), so it is nonminimal. Thus no entire lift is strictly ergodic either. This strengthens the already delivered general minimal refutation of the same Question 1.10 and uses the same problem slug; it is not a second solved problem. Priority remains unestablished, and the coboundary mechanism has prior literature."))), DescribeRole.Theorem,
                new OpenProblemResolutionClaim(ProblemSlugRef.Create("kang-jager-2026-universal-permutative-lift-refutation"), ResolutionKind.Refuted))),
            [ DocumentEdge.Dependency.Create(GidRef.Create("D5/S1/Dynamics/Symbolic/PermutativeLifts/BalancedLiftSplitting")),
              DocumentEdge.Dependency.Create(GidRef.Create("D5/S1/Dynamics/Symbolic/PermutativeLifts/BalancedUniqueErgodic")),
              DocumentEdge.Dependency.Create(GidRef.Create("D5/S1/Dynamics/Symbolic/PermutativeLifts/BalancedRegularity")),
              DocumentEdge.Dependency.Create(GidRef.Create("D5/S1/Dynamics/Symbolic/PermutativeLifts/UniversalRefutation")) ]));
}
